#include<bits/stdc++.h>
#define int long long
using namespace std;
int mod=1e9+7;
int c[1119][1119],a[1111];
void akioi(){
	int n,m,ans=1,sum=0;
	cin>>n>>m;
	int g=n;
	for(int i=1;i<=m;i++){
		cin>>a[i];
		sum+=a[i];
	}
	if(sum!=n){
		n++;
	}
	for(int i=1;i<=m;i++){
		ans=(ans*c[n][a[i]])%mod;
		n-=a[i];
	}
	cout<<ans<<endl;
}
signed main(){
	int t;
	cin>>t;
	c[0][0]=1;
	for(int i=1;i<=1111;i++){
		c[i][0]=1;
	}
	for(int i=1;i<=1111;i++){
		for(int j=1;j<=1111;j++){
			c[i][j]=(c[i-1][j-1]+c[i-1][j])%mod;
		}
	}
	while(t--){
		akioi(); 
	}
	return 0;
}
